const digits = p => { let d = (p || '').toString().replace(/\D/g, ''); if (d.startsWith('0040')) d = d.slice(4); else if (d.startsWith('40') && d.length > 10) d = d.slice(2); return d.replace(/^0+/, ''); };
const samePhone = (a, b) => { const x = digits(a), y = digits(b); return x && y && (x === y || x.endsWith(y) || y.endsWith(x)); };
const nameOf = rec => rec.pacient || rec.patient || rec.name || '';
const STATE = { 'programat': 'scheduled', 'confirmat': 'confirmed', 'anulat': 'cancelled', 'incheiat': 'completed', 'nu s-a prezentat': 'no_show', 'trebuie reprogramat': 'needs_reschedule', 'reprogramat': 'rescheduled' };
const stateOf = rec => STATE[norm(rec.state)] || rec.state || null;
const isCancelled = rec => stateOf(rec) === 'cancelled';
