const hashRef = key => { let h = 5381; for (let i = 0; i < key.length; i++) h = ((h * 33) ^ key.charCodeAt(i)) >>> 0; return h.toString(36).toUpperCase().slice(-4).padStart(4, '0'); };
function collect(q, patientResp, scanResps) {
