let cached = null;
try { const cc = $('MAN Scan Cache').first().json; if (cc && cc._cache_hit && Array.isArray(cc._cached_recs)) cached = cc._cached_recs; } catch (e) {}
let recs;
if (cached) {
  recs = cached;  // already deduped, cancelled ones dropped, sorted, each carrying its _ref
} else {
  const pr = $('MAN get_schedule_patient.php').first().json;
  const scans = $('MAN get_schedule.php').all().map(i => i.json);
  if (pr.statusCode !== 200 && scans.every(r => r.statusCode !== 200)) {
    return [{ json: { _error: true, success: false, error: 'evolvo_api_error', step: 'find', status: pr.statusCode } }];
